from xml.dom import pulldom
SMALL_SAMPLE = '<?xml version="1.0"?>\n<html xmlns="http://www.w3.org/1999/xhtml" xmlns:xdc="http://www.xml.com/books">\n<!-- A comment -->\n<title>Introduction to XSL</title>\n<hr/>\n<p><xdc:author xdc:attrib="prefixed attribute" attrib="other attrib">A. Namespace</xdc:author></p>\n</html>'

def _t():
    """Ensure expandItem works as expected."""
    items = pulldom.parseString(SMALL_SAMPLE)
    for evt, item in items:
        if evt == pulldom.START_ELEMENT and item.tagName == 'title':
            items.expandNode(item)
            assert 1 == len(item.childNodes), ('assertEqual', 1, len(item.childNodes))
            break
    else:
        raise AssertionError('No "title" element detected in SMALL_SAMPLE!')
    for evt, node in items:
        if evt == pulldom.START_ELEMENT:
            break
    assert 'hr' == node.tagName, ('assertEqual', 'hr', node.tagName)
    items.expandNode(node)
    assert next(items)[0] == pulldom.CHARACTERS, ('assertEqual', next(items)[0], pulldom.CHARACTERS)
    evt, node = next(items)
    assert node.tagName == 'p', ('assertEqual', node.tagName, 'p')
    items.expandNode(node)
    next(items)
    evt, node = next(items)
    assert node.tagName == 'html', ('assertEqual', node.tagName, 'html')
    try:
        next(items)
    except StopIteration as _exc:
        pass
    else:
        raise AssertionError('assertRaises: did not raise')
    items.clear()
    assert items.parser is None, ('assertIsNone', items.parser)
    assert items.stream is None, ('assertIsNone', items.stream)
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')
